<script>function expenseForm(rows,plafonds,vatRate){rows=rows.map(row=>({...row,amount_includes_vat:['1',1,true,'true'].includes(row.amount_includes_vat),is_extra:['1',1,true,'true'].includes(row.is_extra)}));return{rows,plafonds,vatRate,deletedRows:[],get selectedYear(){return document.querySelector('[name=planning_year_id]')?.value},errors:@js($errors->toArray()),add(type){this.rows.push({id:null,local_key:'row-new-'+Date.now(),position:this.rows.length+1,vendor_id:'',type,description:'',quantity:'1.000000',unit_price:'0.000000',entered_amount:'0.000000',amount_includes_vat:false,vat_rate:this.vatRate,is_extra:false,funded_plafond_expense_id:'',spend_date:'',period_start:'',period_end:'',distribution:'',external_reference:'',lock_version:null})},remove(index){let row=this.rows[index];if(this.rows.length<2)return;if(row.id&&row.lock_version)this.deletedRows.push({id:row.id,lock_version:row.lock_version});this.rows.splice(index,1)}}}</script>
